#include "module.h"
#include <sqlite3.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#define MAX_DB 64
static const GSNativeAPI *api;static sqlite3 *dbs[MAX_DB];
static sqlite3* db_arg(GSValue*a,size_t n){if(n<1)return NULL;double d=api->number_value(a[0]);if(d<1||d>MAX_DB||d!=(double)(int)d)return NULL;return dbs[(int)d-1];}
static int bind_params(sqlite3_stmt*st,GSValue params){if(params.type!=V_ARRAY)return 1;size_t count=api->array_count(params);for(size_t i=0;i<count;i++){GSValue v=api->array_get(params,i);int rc=SQLITE_MISMATCH;int idx=(int)i+1;switch(v.type){case V_NULL:rc=sqlite3_bind_null(st,idx);break;case V_NUMBER:rc=sqlite3_bind_double(st,idx,v.as.number);break;case V_BOOL:rc=sqlite3_bind_int(st,idx,v.as.boolean);break;case V_STRING:rc=sqlite3_bind_text(st,idx,api->cstring(v),-1,SQLITE_TRANSIENT);break;default:return 0;}if(rc!=SQLITE_OK)return 0;}return 1;}
static GSValue open_fn(GSValue*a,size_t n){if(n<1)return api->null();const char*p=api->cstring(a[0]);if(!p)return api->null();for(int i=0;i<MAX_DB;i++)if(!dbs[i]){sqlite3*db=NULL;if(sqlite3_open_v2(p,&db,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE|SQLITE_OPEN_FULLMUTEX,NULL)!=SQLITE_OK){if(db)sqlite3_close(db);return api->null();}dbs[i]=db;return api->number(i+1);}return api->null();}
static GSValue close_fn(GSValue*a,size_t n){sqlite3*db=db_arg(a,n);if(!db)return api->boolean(0);int idx=(int)api->number_value(a[0])-1;int rc=sqlite3_close(db);if(rc==SQLITE_OK){dbs[idx]=NULL;return api->boolean(1);}return api->boolean(0);}
static GSValue exec_fn(GSValue*a,size_t n){sqlite3*db=db_arg(a,n);if(!db||n<2)return api->null();const char*sql=api->cstring(a[1]);if(!sql)return api->null();sqlite3_stmt*st=NULL;if(sqlite3_prepare_v2(db,sql,-1,&st,NULL)!=SQLITE_OK)return api->null();if(n>2&&!bind_params(st,a[2])){sqlite3_finalize(st);return api->null();}int rc;do{rc=sqlite3_step(st);}while(rc==SQLITE_ROW);int ok=rc==SQLITE_DONE;sqlite3_finalize(st);if(!ok)return api->null();GSValue out=api->object();api->object_set(&out,"changes",api->number((double)sqlite3_changes(db)));api->object_set(&out,"last_id",api->number((double)sqlite3_last_insert_rowid(db)));return out;}
static GSValue query_fn(GSValue*a,size_t n){sqlite3*db=db_arg(a,n);if(!db||n<2)return api->null();const char*sql=api->cstring(a[1]);if(!sql)return api->null();sqlite3_stmt*st=NULL;if(sqlite3_prepare_v2(db,sql,-1,&st,NULL)!=SQLITE_OK)return api->null();if(n>2&&!bind_params(st,a[2])){sqlite3_finalize(st);return api->null();}GSValue rows=api->array();int rc;while((rc=sqlite3_step(st))==SQLITE_ROW){GSValue row=api->object();int cols=sqlite3_column_count(st);for(int i=0;i<cols;i++){const char*k=sqlite3_column_name(st,i);GSValue v;switch(sqlite3_column_type(st,i)){case SQLITE_INTEGER:case SQLITE_FLOAT:v=api->number(sqlite3_column_double(st,i));break;case SQLITE_TEXT:v=api->string((const char*)sqlite3_column_text(st,i));break;case SQLITE_NULL:v=api->null();break;case SQLITE_BLOB:{const unsigned char*b=sqlite3_column_blob(st,i);int z=sqlite3_column_bytes(st,i);char*hex=malloc((size_t)z*2+1);if(!hex){sqlite3_finalize(st);return api->null();}static const char h[]="0123456789abcdef";for(int j=0;j<z;j++){hex[j*2]=h[b[j]>>4];hex[j*2+1]=h[b[j]&15];}hex[z*2]=0;v=api->string(hex);free(hex);break;}default:v=api->null();}api->object_set(&row,k?k:"",v);}api->array_push(&rows,row);}sqlite3_finalize(st);return rc==SQLITE_DONE?rows:api->null();}
static GSValue error_fn(GSValue*a,size_t n){sqlite3*db=db_arg(a,n);return db?api->string(sqlite3_errmsg(db)):api->null();}
GSValue greenServeFE_module_init(const GSNativeAPI*napi){api=napi;GSValue m=api->object();api->object_set(&m,"open",api->native(open_fn));api->object_set(&m,"close",api->native(close_fn));api->object_set(&m,"exec",api->native(exec_fn));api->object_set(&m,"query",api->native(query_fn));api->object_set(&m,"error",api->native(error_fn));return m;}
